package main

import (
	"bufio"
	"fmt"
	"os"
)

const primeBits = 29
const rowBoundBits = 10

// the 35 smallest primes above 10^9, between 2^29 and 2^30; generated by 1914_matrix_table.py
var primes = [...]int64{
	1000000007, 1000000009, 1000000021, 1000000033, 1000000087,
	1000000093, 1000000097, 1000000103, 1000000123, 1000000181,
	1000000207, 1000000223, 1000000241, 1000000271, 1000000289,
	1000000297, 1000000321, 1000000349, 1000000363, 1000000403,
	1000000409, 1000000411, 1000000427, 1000000433, 1000000439,
	1000000447, 1000000453, 1000000459, 1000000483, 1000000513,
	1000000531, 1000000579, 1000000607, 1000000613, 1000000637,
}

func power(value, exponent, modulus int64) int64 {
	result := int64(1)
	for exponent > 0 {
		if exponent&1 != 0 {
			result = result * value % modulus
		}
		value = value * value % modulus
		exponent >>= 1
	}
	return result
}

func determinantModulo(matrix [][]int64, modulus int64) int64 {
	size := len(matrix)
	values := make([][]int64, size)
	for i, row := range matrix {
		values[i] = make([]int64, size)
		for j, value := range row {
			values[i][j] = (value%modulus + modulus) % modulus
		}
	}
	determinant := int64(1)
	for column := 0; column < size; column++ {
		pivot := column
		for pivot < size && values[pivot][column] == 0 {
			pivot++
		}
		if pivot == size {
			return 0
		}
		if pivot != column {
			values[pivot], values[column] = values[column], values[pivot]
			determinant = modulus - determinant
		}
		pivotLine := values[column]
		pivotValue := pivotLine[column]
		determinant = determinant * pivotValue % modulus
		inverse := power(pivotValue, modulus-2, modulus)
		for row := column + 1; row < size; row++ {
			line := values[row]
			if line[column] == 0 {
				continue
			}
			factor := line[column] * inverse % modulus
			for target := column + 1; target < size; target++ {
				value := line[target] - factor*pivotLine[target]%modulus
				if value < 0 {
					value += modulus
				}
				line[target] = value
			}
			line[column] = 0
		}
	}
	return determinant
}

func isUnimodular(matrix [][]int64) bool {
	needed := (rowBoundBits*len(matrix) + primeBits) / primeBits
	sign := 0
	for _, modulus := range primes[:needed] {
		determinant := determinantModulo(matrix, modulus)
		current := 0
		if determinant == 1 {
			current = 1
		} else if determinant == modulus-1 {
			current = -1
		}
		if current == 0 || (sign != 0 && sign != current) {
			return false
		}
		sign = current
	}
	return true
}

func main() {
	input := bufio.NewReader(os.Stdin)
	var size int
	fmt.Fscan(input, &size)
	matrix := make([][]int64, size)
	for row := range matrix {
		matrix[row] = make([]int64, size)
		for column := range matrix[row] {
			fmt.Fscan(input, &matrix[row][column])
		}
	}
	if isUnimodular(matrix) {
		fmt.Println("Death")
	} else {
		fmt.Println("Power of magic saves lives")
	}
}
